#!/usr/bin/env python3
# Generated by Claude Fable 5.1 (Anthropic)
"""Autoware phase tables: one table per phase — warm-up (1→2) and execution
(2→3) — rows = values Autoware's own nodes report on /diagnostics, columns =
baseline / lttng / lttng+nsys. Cell = MEAN of all diag values whose header
stamp falls into the phase, pooled over the mode's runs (not medians), with
the pooled sample count; deltas vs baseline.

Phase instants per run (sim time, from diag.log; notes/aw_phases_provenance.md):
  (1) first nonzero header stamp (= first /clock)
  (2) pipeline_latency_monitor's first tick with the tracker reported
  (3) last stamp (bag end; the sim clock freezes)

usage: phase_tables.py <overhead_aw_dir> [--tex out_dir]
"""
import glob, os, sys
sys.path.insert(0, os.path.dirname(os.path.abspath(__file__)))
from analyze_overhead import parse_diag, fnum  # noqa: E402

MODES = [("baseline", "baseline"), ("lttng", "lttng"), ("nsys", "lttng+nsys")]
# (row label, status-name substring, value key, scale, sanity predicate or None)
ROWS = [
    ("crop_box_filter_self proc [ms]", "crop_box_filter_self", "Processing time (ms)", 1, None),
    ("crop_box_filter_self pipeline [ms]", "crop_box_filter_self", "Pipeline latency (ms)", 1, None),
    ("distortion_corrector proc [ms]", "distortion_corrector_node", "Processing time (ms)", 1, None),
    ("distortion_corrector pipeline [ms]", "distortion_corrector_node", "Pipeline latency (ms)", 1, None),
    ("ring_outlier_filter proc [ms]", "ring_outlier_filter", "Processing time (ms)", 1, None),
    ("ring_outlier_filter pipeline [ms]", "ring_outlier_filter", "Pipeline latency (ms)", 1, None),
    ("concatenate_data proc [ms]", "concatenate_data", "Processing time (ms)", 1, None),
    ("concatenate_data pipeline [ms]", "concatenate_data", "Pipeline latency (ms)", 1, None),
    ("ndt sensor delay [ms]", "ndt_scan_matcher", "sensor_points_delay_time_sec", 1e3, None),
    ("ndt iterations [#]", "ndt_scan_matcher", "iteration_num", 1, None),
    ("ekf pose delay [ms]", "localization", "pose_delay_time", 1e3, None),
    ("occupancy_grid proc [ms]", "occupancy_grid_map_node", "processing time(ms)", 1, None),
    ("centerpoint proc [ms] (GPU; >0 = inference ran)", "processing_time_status", "processing_time_ms", 1, lambda v: v > 0),
    ("centerpoint consecutive delay [ms]", "processing_time_status", "consecutive_processing_delay_ms", 1, None),
    ("map_based_prediction proc [ms]", "map_based_prediction:", "processing_time_ms", 1, None),
    ("tracker detection delay [ms]", "multi_object_tracker", "Detection delay (s)", 1e3, None),
    ("monitor: Total Latency [ms]", "pipeline_latency_monitor", "Total Latency (ms)", 1, None),
    ("monitor: multi_object_tracker [ms]", "pipeline_latency_monitor", "multi_object_tracker", 1, None),
    ("monitor: map_based_prediction [ms]", "pipeline_latency_monitor", "map_based_prediction", 1, None),
    ("tsm objects rate [Hz]", "object_recognition_objects", "measured_rate", 1, lambda v: 0 < v < 1000),
    ("tsm obstacle pc rate [Hz]", "obstacle_segmentation_pointcloud", "measured_rate", 1, lambda v: 0 < v < 1000),
]


def run_phases(diag):
    stamps = [e["_t"] for v in diag.values() for e in v if e.get("_t")]
    t0, t3 = min(stamps), max(stamps)
    lat = [e for name, v in diag.items() if "pipeline_latency_monitor" in name for e in v]
    t2 = min((e["_t"] for e in lat if e.get("_t")
              and "multi_object_tracker" not in str(e.get("uninitialized_inputs", ""))), default=None)
    return t0, t2, t3


def collect(root):
    """mode -> phase -> row label -> list of values (pooled over runs)."""
    data = {m: {"warm-up": {}, "execution": {}} for m, _ in MODES}
    spans = {m: [] for m, _ in MODES}
    for m, _ in MODES:
        for d in sorted(glob.glob(os.path.join(root, f"{m}_*"))):
            diag = parse_diag(os.path.join(d, "diag.log"))
            t0, t2, t3 = run_phases(diag)
            spans[m].append((os.path.basename(d), t2 - t0, t3 - t2))
            for label, sub, key, scale, sane in ROWS:
                for name, entries in diag.items():
                    if sub not in name:
                        continue
                    for e in entries:
                        t = e.get("_t")
                        if not t:
                            continue
                        v = fnum(e, key)
                        if v is None or (sane and not sane(v)):
                            continue
                        ph = "warm-up" if t < t2 else "execution"
                        data[m][ph].setdefault(label, []).append(v * scale)
    return data, spans


def mean(vs):
    return sum(vs) / len(vs) if vs else None


def markdown(data, spans):
    out = []
    for m, _ in MODES:
        out.append(f"{m}: " + "; ".join(f"{n}: warm-up {w:.1f} s, execution {x:.1f} s" for n, w, x in spans[m]))
    for ph, title in (("warm-up", "(1)→(2) warm-up"), ("execution", "(2)→(3) execution")):
        out.append(f"\n### {title} — mean of all diag values in the phase, pooled over 3 runs [n]\n")
        out.append("| value (reporting node) | baseline | lttng Δ | lttng+nsys Δ |")
        out.append("|---|--:|--:|--:|")
        for label, *_ in ROWS:
            b = data["baseline"][ph].get(label, [])
            mb = mean(b)
            cells = [f"{mb:.2f} [{len(b)}]" if mb is not None else "—"]
            for m in ("lttng", "nsys"):
                v = data[m][ph].get(label, [])
                mv = mean(v)
                if mv is None or mb is None:
                    cells.append("—")
                else:
                    d = f"{(mv - mb) / mb * 100:+.0f}%" if abs(mb) > 1e-9 else f"→{mv:.2f}"
                    cells.append(f"{mv:.2f} ({d}) [{len(v)}]")
            out.append(f"| {label} | " + " | ".join(cells) + " |")
    return "\n".join(out)


def tex(data, spans, out_dir):
    os.makedirs(out_dir, exist_ok=True)
    for ph, title, tag in (("warm-up", "warm-up phase (1)$\\rightarrow$(2)", "warmup"),
                           ("execution", "execution phase (2)$\\rightarrow$(3)", "execution")):
        L = ["% Generated by Claude Fable 5.1 (Anthropic)",
             r"\begin{table}[t]\centering\scriptsize",
             r"\caption{Autoware, " + title + r": mean of every value the nodes themselves "
             r"report on \texttt{/diagnostics} with a header stamp inside the phase, pooled "
             r"over three runs per mode ($n$ in brackets); $\Delta$ vs.\ the untraced baseline.}",
             rf"\label{{tab:aw-phase-{tag}}}",
             r"\begin{tabular}{lrrr}", r"\toprule",
             r"value & baseline & LTTng $\Delta$ & LTTng+nsys $\Delta$ \\", r"\midrule"]
        for label, *_ in ROWS:
            b = data["baseline"][ph].get(label, [])
            mb = mean(b)
            cells = [f"{mb:.1f} [{len(b)}]" if mb is not None else "--"]
            for m in ("lttng", "nsys"):
                v = data[m][ph].get(label, [])
                mv = mean(v)
                if mv is None or mb is None:
                    cells.append("--")
                elif abs(mb) < 1e-9:
                    cells.append((r"$\pm$0" if abs(mv) < 1e-9 else rf"$\rightarrow${mv:.2f}") + f" [{len(v)}]")
                else:
                    d = f"{(mv - mb) / mb * 100:+.0f}".replace("-", "--") + r"\%"
                    cells.append(f"{d} [{len(v)}]")
            L.append(label.replace("_", r"\_").replace("#", r"\#").replace(">", "$>$") + " & " + " & ".join(cells) + r" \\")
        L += [r"\bottomrule", r"\end{tabular}", r"\end{table}"]
        path = os.path.join(out_dir, f"aw_phase_{tag}.tex")
        open(path, "w").write("\n".join(L) + "\n")
        print(f"→ {path}", file=sys.stderr)


if __name__ == "__main__":
    root = sys.argv[1]
    data, spans = collect(root)
    print(markdown(data, spans))
    if "--tex" in sys.argv:
        tex(data, spans, sys.argv[sys.argv.index("--tex") + 1])
